  "sim.egg-incubator.title": "Inkubator Telur",
  "sim.egg-incubator.desc": "Atur suhu, kelembapan, dan rotasi telur di tempat penetasan untuk memaksimalkan tingkat penetasan.",
  "sim.dairy-farm.title": "Peternakan Susu",
  "sim.dairy-farm.desc": "Jalankan usaha peternakan susu skala kecil: jadwal pakan, siklus pemerahan, dan kesehatan kawanan untuk memaksimalkan hasil.",
  "sim.poultry-farm.title": "Peternakan Unggas",
  "sim.poultry-farm.desc": "Kelola peternakan unggas komersial—pakan, kesehatan, dan target produksi untuk flok pedaging dan petelur.",
  "sim.cattle-dairy.title": "Ternak & Susu",
  "sim.cattle-dairy.desc": "Pantau peternakan sapi dan unit susu, menyeimbangkan pengelolaan padang, pembiakan, dan produksi susu.",
  "sim.sheep-farm.title": "Peternakan Domba",
  "sim.sheep-farm.desc": "Jalankan peternakan domba melalui siklus musiman: masa beranak, pencukuran, dan penjualan ke pasar.",
  "sim.network-noc.title": "Network NOC",
  "sim.network-noc.desc": "Bertindak sebagai insinyur Network Operations Centre—diagnosis dan selesaikan insiden infrastruktur secara langsung di bawah tekanan.",
  "sim.mobile-repair.title": "Bengkel Perbaikan Mobile",
  "sim.mobile-repair.desc": "Diagnosa dan perbaiki smartphone—penggantian layar, masalah baterai, dan kerusakan motherboard.",
  "sim.laptop-repair.title": "Bengkel Perbaikan Laptop",
  "sim.laptop-repair.desc": "Troubleshoot dan perbaiki laptop: kerusakan perangkat keras, masalah BIOS, dan penggantian komponen.",
  "sim.perfume-lab.title": "Perfume Lab",
  "sim.perfume-lab.desc": "Campurkan minyak esensial dan senyawa aroma untuk menciptakan parfum khas serta memenuhi tolok ukur kualitas.",
  "sim.detergent-lab.title": "Lab Deterjen",
  "sim.detergent-lab.desc": "Rumuskan produk pembersih—seimbangkan surfaktan, pengisi, dan uji performa dalam batas anggaran.",
  "sim.skin-care-lab.title": "Lab Perawatan Kulit",
  "sim.skin-care-lab.desc": "Kembangkan dan uji formulasi kosmetik, sesuai standar keamanan dan target efektivitas.",
  "sim.woodworking.title": "Bengkel Pertukangan Kayu",
  "sim.woodworking.desc": "Jalankan bengkel pertukangan kayu custom: rencanakan pekerjaan, kelola bahan, dan kirim furnitur tepat waktu sesuai anggaran.",
  "sim.aluminum-glazing.title": "Aluminium & Kaca",
  "sim.aluminum-glazing.desc": "Kelola bisnis fabrikasi aluminium dan pemasangan kaca dari penawaran hingga selesai di lokasi.",
  "sim.global-kitchen.title": "Dapur Global",
  "sim.global-kitchen.desc": "Pimpin dapur restoran: kelola menu, staf, biaya, dan kepuasan pelanggan di berbagai shift layanan.",
  "sim.chocolate-factory.title": "Pabrik Cokelat",
  "sim.chocolate-factory.desc": "Operasikan pabrik confectionery—pengadaan kakao, penjadwalan produksi, dan kontrol kualitas.",
  "sim.solar-energy.title": "Pembangkit Energi Surya",
  "sim.solar-energy.desc": "Rancang dan operasikan instalasi surya—tentukan ukuran panel, kelola ekspor ke jaringan, dan lacak ROI.",
  "sim.hvac-systems.title": "Sistem HVAC",
  "sim.hvac-systems.desc": "Pasang dan rawat sistem pemanas, ventilasi, dan tata udara untuk gedung komersial.",
  "sim.logistics-supply.title": "Logistik & Rantai Pasok",
  "sim.logistics-supply.desc": "Optimalkan operasi gudang, rute armada, dan hubungan pemasok untuk mencapai KPI pengiriman.",
  "sim.barber-salon.title": "Salon Barbershop",
  "sim.barber-salon.desc": "Kelola barbershop: janji temu, jadwal staf, penetapan harga, dan strategi retensi pelanggan.",
  "sim.board-surgeon.title": "Ahli Bedah",
  "sim.board-surgeon.desc": "Ambil keputusan bedah berisiko tinggi di ruang operasi simulasi—manajemen waktu dan keselamatan pasien.",
  "sim.english-journey.title": "Perjalanan Bahasa Inggris",
  "sim.english-journey.desc": "Bimbing peserta melalui program bahasa Inggris yang terstruktur, menyesuaikan dengan berbagai tingkat kemampuan.",
  "sim.music-training.title": "Studio Pelatihan Musik",
  "sim.music-training.desc": "Jalankan sekolah musik: jadwalkan les, kelola instrumen, dan pantau progres siswa menuju resital.",
  "sim.trade-tycoon.title": "Trade Tycoon",
  "sim.trade-tycoon.desc": "Bangun kerajaan perdagangan—beli saat harga rendah, jual saat harga tinggi, kelola inventaris dan arus kas di berbagai pasar.",
  "sim.vehicle-diagnostics.title": "Simulator Diagnostik & Perbaikan Kendaraan",
