  "jungle.howTo.1": "Kamu terdampar di hutan — buat pilihan untuk bertahan hidup",
  "jungle.howTo.2": "Setiap pilihan memengaruhi HP dan skor kamu secara berbeda",
  "jungle.howTo.3": "Jika HP kamu mencapai 0, permainan berakhir",
  "jungle.howTo.4": "Bertahan hidup di semua 8 skenario untuk menang!",
  "jungle.scene6": "Kamu menemukan seekor burung terluka. Apa yang kamu lakukan?",
  "jungle.s6c1": "Bawa dengan hati-hati — bisa mengarah ke sebuah jalan (+5 HP, +25 poin)",
  "jungle.s6c2": "Tinggalkan — merawatnya buang energi (0 HP, +10 poin)",
  "jungle.scene7": "Sebuah sungai menghalangi jalanmu. Airnya terlihat cepat.",
  "jungle.s7c1": "Buat rakit dari kayu gelondongan (−5 HP, +40 poin)",
  "jungle.s7c2": "Jalan menyusuri hulu untuk mencari tempat menyeberang yang dangkal (+10 HP, +20 poin)",
  "jungle.scene8": "Kamu melihat asap di kejauhan.",
  "jungle.s8c1": "Pergi ke arah asap — mungkin ada penyelamatan! (+15 HP, +45 poin)",
  "jungle.s8c2": "Hindari — mungkin ada kebakaran hutan (−5 HP, +15 poin)",
  "jungle.scene9": "Malam turun. Kamu butuh tempat berlindung.",
  "jungle.s9c1": "Naik ke pohon tinggi untuk tetap aman dari predator (+10 HP, +30 poin)",
  "jungle.s9c2": "Bangun tempat berlindung di tanah dengan ranting (−5 HP, +35 poin)",
  "jungle.scene10": "Kamu menemukan buah yang tidak kamu kenali. Kamu sangat lapar.",
  "jungle.s10c1": "Makan — kamu hampir kelaparan! (−20 HP, +30 poin)",
  "jungle.s10c2": "Coba sedikit dulu di kulitmu (0 HP, +20 poin)",
  "jungle.scene11": "Sebuah ular besar meliuk di jalur.",
  "jungle.s11c1": "Mundur pelan-pelan dan cari jalan memutar (+5 HP, +30 poin)",
  "jungle.s11c2": "Coba menakutinya (−25 HP, +40 poin)",
  "jungle.scene12": "Kamu mendengar suara air terjun — persediaan airmu sangat kritis.",
  "jungle.s12c1": "Ikuti suaranya untuk mencari air segar (+20 HP, +35 poin)",
  "jungle.s12c2": "Abaikan dan terus berjalan (−15 HP, +20 poin)",
  "jungle.scene13": "Badai mendekat dengan cepat.",
  "jungle.s13c1": "Cari tempat tinggi dan berlindung (+10 HP, +25 poin)",
  "jungle.s13c2": "Terus bergerak untuk menghindar (−10 HP, +30 poin)",
  "jungle.scene14": "Kamu menemukan gua. Keadaannya mulai gelap.",
  "jungle.s14c1": "Masuk ke gua untuk berlindung (+15 HP, +30 poin)",
  "jungle.s14c2": "Tidur di bawah pohon — gua mungkin sudah ditempati (+5 HP, +20 poin)",
  "jungle.scene15": "Kamu sangat kelelahan. Area terbuka di depan terlihat aman.",
  "jungle.s15c1": "Beristirahat dan pulih (+20 HP, +20 poin)",
  "jungle.s15c2": "Teruskan perjalanan — beristirahat di sini berbahaya (−5 HP, +30 poin)",
  "jungle.scene16": "Kamu menemukan peta tua yang diukir di pohon.",
  "jungle.s16c1": "Ikuti arah peta (+5 HP, +40 poin)",
  "jungle.s16c2": "Abaikan — mungkin sudah tidak berlaku (0 HP, +10 poin)",
  "jungle.scene17": "Babi hutan menyerbu melewati jalanmu.",
  "jungle.s17c1": "Naik ke pohon terdekat segera (+5 HP, +30 poin)",
  "jungle.s17c2": "Berdiri di tempat dan teriak (−20 HP, +35 poin)",
  "jungle.scene18": "Kamu menemukan kamp yang ditinggalkan dengan perbekalan.",
  "jungle.s18c1": "Ambil semua yang berguna (+20 HP, +50 poin)",
  "jungle.s18c2": "Tinggalkan saja — mungkin nanti dibutuhkan (0 HP, +10 poin)",
  "jungle.scene19": "Sebuah monyet mencuri kantong makananmu!",
  "jungle.s19c1": "Kejar monyet (−10 HP, +40 poin)",
  "jungle.s19c2": "Biarkan saja — tidak sepadan dengan usaha (+0 HP, +15 poin)",
  "jungle.scene20": "Kamu mendengar helikopter di atas.",
  "jungle.s20c1": "Nyalakan api sinyal segera! (+30 HP, +60 poin)",
  "jungle.s20c2": "Kibaskan tanganmu — mungkin melihatmu (+5 HP, +40 poin)",
