  "uno.howTo.1": "Cocokkan kartu teratas tumpukan berdasarkan warna atau angka",
  "uno.howTo.2": "Ketuk kartu di tanganmu untuk memainkannya",
  "uno.howTo.3": "Jika tidak ada yang cocok, ketuk Draw untuk menambahkan kartu",
  "uno.howTo.4": "Yang pertama menghabiskan kartu di tangannya menang!",
  "briscola.howTo.1": "Briscola adalah permainan kartu khas Italia",
  "briscola.howTo.2": "Jenis truf (Briscola) mengalahkan semua jenis lainnya",
  "briscola.howTo.3": "Menangkan trik untuk mendapatkan poin — As=11, 3=10, King=4, Queen=3, Jack=2",
