  "card99.howTo.1": "Mainkan kartu agar total berjalan tetap di bawah atau sama dengan 99",
  "card99.howTo.2": "Kartu spesial: King=0, Queen=simpat/bertahan, Jack=−10, As=1 atau 11",
  "card99.howTo.3": "Dorong total melewati 99 dan kamu kehilangan satu nyawa",
  "card99.howTo.4": "Pemain terakhir yang masih punya nyawa menang!",
  "dominoes.howTo.1": "Cocokkan angka di ujung rantai domino",
