  "dominoes.howTo.3": "Ambil dari tumpukan jika tidak bisa main",
  "dominoes.howTo.4": "Yang pertama menghabiskan kartu di tangannya (atau pip paling sedikit) menang!",
  "farkle.howTo.1": "Lempar 6 dadu dan sisihkan dadu yang mendapat skor",
  "farkle.howTo.2": "1s = 100 poin · 5s = 50 poin · Tiga sejenis = angka wajah × 100",
  "farkle.howTo.3": "Jika NO dadu mendapat skor dalam satu lemparan, itu FARKLE — giliranmu hangus!",
  "farkle.howTo.4": "Simpan poinmu untuk menjaganya, atau lempar lagi untuk risiko/imbalan lebih besar",
  "quiz.howTo.1": "Jawab 20 pertanyaan pilihan ganda secepat mungkin",
  "quiz.howTo.2": "Setiap pertanyaan punya waktu 3 detik — jawab cepat!",
